#!/usr/bin/env python3
"""Package the receive boards (AB1A, AB1B: AD7389-4 build with the +3V3D island on In4) into releases/RX_<REV>/ with Gerber and drill zips, BOM, pick-and-place, netlist, KiCad board and rules,
functional schematic PDF, component models (VRML) and a glTF export, per-board CHECKS.md, BLOCKERS.md and a hash manifest. Refuses to run if the sign-off has a FAIL or is missing, if data/ is stale
against work/, or if the release folder exists (new versions get new names). Copies from the COMMITTED data/ folders. MODELED / tool-checked only.
BLOCKER 1 (the AD7389-4 exposed-pad PLACEHOLDER) was carried by RX_r1 only: closed in RX_r2 (B1, land = Ultra Librarian CP-24-25_ADI, agrees with ADI Fig. 43).
The remaining BLOCKER entries keep their numbers so a reader of RX_r1 can follow them.
usage: release_rx.py REV      e.g. r1 -> releases/RX_r1"""
import sys, os, json, shutil, subprocess, datetime, glob, zipfile
rev = sys.argv[1] if len(sys.argv) > 1 else "r1"; out = f"{os.environ.get('ARX_RELEASE_ROOT', 'releases')}/RX_{rev}"
def die(m): print("release-rx REFUSED:", m); sys.exit(1)
if os.path.exists(out): die(f"{out} exists: new versions get new names")
SJ = os.environ.get("ARX_SIGNOFF_JSON", "data/results/SIGNOFF_STATUS.json")
try: S = json.load(open(SJ))
except Exception: die(f"{SJ} missing: run make signoff")
if S["counts"]["FAIL"]: die(f"the sign-off has {S['counts']['FAIL']} FAIL")
if subprocess.run([sys.executable, "scripts/publish_data.py", "--check"], capture_output=True).returncode: die("data/ is stale against work/: run scripts/publish_data.py, review, commit, then sign off again")
BLOCKERS = ["BLOCKER 2 (interface): SDI is tied to ground (the datasheet does not say whether that is allowed) and no software reset is issued; the 2-wire readout (SDOA = channels A then C, SDOB = channel B, J2 SDO3 unused on AB1A) needs a CB1D firmware change.",
            "BLOCKER 3 (supply): the extra +3V3D load (about 25 mA, 89 mW typical from the datasheet) is not checked against the rail budget.",
            "OPEN: island hatch connectivity has been read back from the Gerbers (gerber_geom) and KiCad-checked, but not opened in a CAM viewer or reviewed by a fabricator (U-CAM-VIEW, U-FAB-DRC); SW1G66, OPA2365 and BAV199 pin maps stay VERIFY; nothing here is built or measured."]
os.makedirs(out); summary = []; unv = S["unverified"]
def cp(src, dst):
    if not os.path.exists(src): return False
    os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy(src, dst); return True
for b in ("AB1A", "AB1B"):
    d = f"{out}/{b}"; n = 0; gd = f"data/gerber/{b}_v1"; files = sorted(glob.glob(gd + "/*"))
    with zipfile.ZipFile(f"{d}_gerber_drill.zip", "w", zipfile.ZIP_DEFLATED) as z:
        for f in files: z.write(f, os.path.basename(f))
    for f in files: n += cp(f, f"{d}/gerber/{os.path.basename(f)}")
    for k in (f"PF233-{b}.kicad_pcb", f"PF233-{b}.kicad_dru", f"PF233-{b}.kicad_pro"): n += cp(f"data/kicad/{k}", f"{d}/kicad/{k}")
    for r in (f"PF233-{b}_BOM.csv", f"PF233-{b}_pickplace.csv", f"PF233-{b}.net", f"PF233-{b}_functional.pdf", f"kicad_drc_{b}.json", f"indep_drc_{b}.json", f"ab1_island_check_{b}.json", f"gerber_ab1_{b}.json", f"gerber_edge_{b}.json", f"{b}_layout.json"): n += cp(f"data/results/{r}", f"{d}/results/{r}")
    for f in sorted(glob.glob("data/kicad/3dmodels/*.wrl")): n += cp(f, f"{d}/kicad/3dmodels/{os.path.basename(f)}")
    glb = f"{d}/models3d/{b}_with_components.glb"; os.makedirs(os.path.dirname(glb), exist_ok=True)
    r = subprocess.run(["kicad-cli", "pcb", "export", "glb", "--subst-models", "--include-tracks", "--include-pads", "--include-zones", "-o", glb, f"data/kicad/PF233-{b}.kicad_pcb"], capture_output=True, text=True); n += os.path.exists(glb)
    st = S["boards"].get(b, {}); lines = [f"# {b}: checks in this release (generated by scripts/release_rx.py from data/results/SIGNOFF_STATUS.json)", "", "Tool-checked / MODELED only. Not fabricated, not measured, not reviewed by a fabricator.", "", "## BLOCKERS", ""] + [f"- {x}" for x in BLOCKERS] + ["", "| check | state | detail |", "|---|---|---|"]
    for c, v in st.items(): lines.append(f"| {c} | {v['state']} | {v['detail']} |")
    lines += ["", "## Still UNVERIFIED (docs/UNVERIFIED.md)", ""] + [f"- {k}: {t}" for k, t in unv.items()]
    open(f"{d}/CHECKS.md", "w").write("\n".join(lines) + "\n")
    states = [v["state"] for v in st.values()]; summary.append((b, n, states.count("PASS"), states.count("UNVERIFIED")))
for r in ("SIGNOFF_STATUS.json",): cp(f"data/results/{r}", f"{out}/shared/{r}")
cp("docs/STATUS.md", f"{out}/STATUS.md"); cp("docs/UNVERIFIED.md", f"{out}/UNVERIFIED.md"); cp("docs/design/FAB_RULES_VERIFIED.md", f"{out}/FAB_RULES_VERIFIED.md"); cp("docs/design/AB1_ROUTING_STATE.md", f"{out}/AB1_ROUTING_STATE.md")
open(f"{out}/BLOCKERS.md", "w").write("# Blockers of this release\n\n" + "\n\n".join(BLOCKERS) + "\n")
git = subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
md = [f"# Receive-board release RX_{rev}", "", f"Commit {git}; {datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}. MODELED / tool-checked only. Not fabricated, not measured, not reviewed by a fabricator. NOT RELEASABLE FOR ORDERING: see BLOCKERS.md.", "",
      "| board | files | checks PASS | UNVERIFIED |", "|---|---|---|---|"] + [f"| {b} | {n} | {p} | {u} |" for b, n, p, u in summary] + ["", "Per-board check lists are in `<board>/CHECKS.md`; hashes in `MANIFEST.csv`. The old ADS8860 / REF5041 AB1 files in data/legacy are SUPERSEDED."]
open(f"{out}/RELEASE.md", "w").write("\n".join(md) + "\n")
subprocess.run([sys.executable, "scripts/manifest.py", f"{out}/MANIFEST.csv", out], check=True)
print(f"release-rx: {out} written; boards: " + ", ".join(f"{b} ({n} files)" for b, n, *_ in summary))
